#!/bin/bash
# Render the ProxySQL config from the template and start ProxySQL.
# Secrets are alphanumeric (generated by setup.sh), so plain sed is safe here.
set -Eeuo pipefail

for v in PROXYSQL_ADMIN_PASSWORD PROXYSQL_MONITOR_PASSWORD WORDPRESS_DB_USER WORDPRESS_DB_PASSWORD; do
    : "${!v:?$v is required}"
done

cp /proxysql/proxysql.cnf.tmpl /etc/proxysql.cnf
for v in PROXYSQL_ADMIN_PASSWORD PROXYSQL_MONITOR_PASSWORD WORDPRESS_DB_USER WORDPRESS_DB_PASSWORD; do
    sed -i "s|@@${v}@@|${!v}|g" /etc/proxysql.cnf
done

# ProxySQL ignores the config file when a runtime DB exists. Drop it so the
# rendered config always wins.
rm -f /var/lib/proxysql/proxysql.db

exec proxysql -f --idle-threads -D /var/lib/proxysql -c /etc/proxysql.cnf
